"""Open Knowledge Format (OKF v0.2) bundle of an ontology snapshot: ``exports/r<rev>/okf/``.

Layout (every path below is bundle-relative; links inside the bundle are bundle-absolute,
``/concepts/<slug>.md``):

* ``index.md`` -- frontmatter ``okf_version: "0.2"`` only, then one section per folder
  listing its files with their descriptions.
* ``log.md`` -- ``## <YYYY-MM-DD>`` then ``- revision r<rev>: generated by autoontology
  <version> from sources ...``.
* ``concepts/<slug>.md`` -- ``type: Business Concept``, one per Term and per document
  concept (a concept folded into a Term by ``same`` is part of the Term's file). Body:
  ``# Schema`` (Terms), ``# Relationships``, ``# Synonyms``, ``# Alignment``, ``# Evidence``
  (quotes with footnotes ``[^e<n>]`` that match ``sources[].id``).
* ``tables/<source>.<table>.md`` -- ``type: Table``, ``resource:
  autoontology://<source>/<schema>.<table>``, ``# Schema`` and the concept(s) it backs.
* ``documents/<slug>.md`` -- ``type: Document``, ``resource`` the file URI (absolute paths)
  or ``autoontology://<source>/<path>`` (paths stored relative to the project), and the
  concepts extracted from it.
* ``validation.json`` -- the result of :func:`validate` over the bundle.

Every concept file carries ``generated: {by: autoontology/<version>, at: <snapshot time>}``
(the OKF actor convention ``<producer>/<version>``; the snapshot time keeps the bundle
deterministic) and ``status: stable``, or ``draft`` for a document concept that waits on a
review proposal (a ``same`` verdict below the accept threshold or from a dry run).
File names keep Hangul (``concepts/계약상태.md``); they are NFC, lower case, and contain
only letters, digits, ``.``, ``_`` and ``-``.
"""

from __future__ import annotations

import json
import re
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path, PurePosixPath
from typing import Any
from urllib.parse import quote, unquote

import yaml

from autoontology import __version__
from autoontology.ontology.model import LITERAL, THING, MergedOntology

OKF_DIR = "okf"
OKF_VERSION = "0.2"
VALIDATION = "validation.json"
RESERVED = frozenset({"index.md", "log.md"})
CONCEPT_TYPE = "Business Concept"
GENERATOR = f"autoontology/{__version__}"
_DATE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_LINK = re.compile(r"(?<!\\)\[(?:[^\]\\]|\\.)*\]\(\s*<?([^)\s>]+)>?(?:\s+\"[^\"]*\")?\s*\)")
_FOOTNOTE_REF = re.compile(r"\[\^([^\]\s]+)\](?!:)")
_SCHEME = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")


class OkfError(RuntimeError):
    """The bundle is not conformant; the message lists the errors."""


# --- names and text -------------------------------------------------------------------------


def slug(text: str, fallback: str = "x") -> str:
    """A file-name slug: NFC, lower case, letters/digits/``._-`` only, starting with a
    letter or digit (Hangul kept)."""
    s = unicodedata.normalize("NFC", str(text or "")).lower()
    s = re.sub(r"[^\w.-]+", "-", s)
    s = re.sub(r"^[^\w]+|[^\w]+$", "", s).lstrip("_")
    return s[:120].rstrip("-._") or fallback


def _unique(base: str, taken: set[str]) -> str:
    name, n = base, 2
    while name in taken or f"{name}.md" in RESERVED:
        name, n = f"{base}-{n}", n + 1
    taken.add(name)
    return name


def _one_line(text: str, limit: int = 240) -> str:
    text = " ".join(str(text or "").split())
    return text if len(text) <= limit else text[: limit - 1].rstrip() + "…"


#: a line start that Markdown reads as a heading, list item, block quote or rule
_BLOCK_START = re.compile(r"^(#|>|[-+*](?=\s|$)|[-*_]{3}|\d+(?=[.)](?:\s|$))|=+\s*$)")


def _escape(text: str) -> str:
    """Inline text (definitions, quotes, labels come from documents and the LLM) that
    cannot open a link, footnote, table cell, raw HTML or a block: ``<`` becomes ``&lt;``
    and a leading ``#``/``>``/list marker/ordered-list number is backslash-escaped."""
    text = " ".join(str(text or "").split())
    text = (
        text.replace("\\", "\\\\")
        .replace("[", "\\[")
        .replace("]", "\\]")
        .replace("|", "\\|")
        .replace("<", "&lt;")
    )
    match = _BLOCK_START.match(text)
    if match is None:
        return text
    if match.group(0)[0].isdigit():  # "1." -> "1\."
        end = match.end()
        return f"{text[:end]}\\{text[end:]}"
    return f"\\{text}"


def _iri_path(path: str) -> str:
    """*path* as an IRI path: ASCII reserved characters percent-encoded, letters kept."""
    return "".join(c if ord(c) > 127 else quote(c, safe="/-._~") for c in path)


def document_resource(path: str, source: str) -> str:
    p = PurePosixPath(path.replace("\\", "/"))
    if p.is_absolute():
        return f"file://{_iri_path(p.as_posix())}"
    return f"autoontology://{_iri_path(source)}/{_iri_path(p.as_posix())}"


def frontmatter(meta: dict[str, Any]) -> str:
    return (
        "---\n"
        + yaml.safe_dump(meta, allow_unicode=True, sort_keys=False, width=1_000_000)
        + "---\n"
    )


def split_frontmatter(text: str) -> tuple[dict[str, Any] | None, str, str | None]:
    """``(frontmatter, body, error)``; frontmatter is None when the file has none."""
    if not text.startswith("---\n") and not text.startswith("---\r\n"):
        return None, text, None
    lines = text.splitlines(keepends=True)
    for i in range(1, len(lines)):
        if lines[i].rstrip("\r\n") == "---":
            raw, body = "".join(lines[1:i]), "".join(lines[i + 1 :])
            try:
                meta = yaml.safe_load(raw)
            except yaml.YAMLError as exc:
                return None, body, f"frontmatter is not YAML ({exc.__class__.__name__})"
            if meta is None:
                meta = {}
            if not isinstance(meta, dict):
                return None, body, "frontmatter is not a mapping"
            return meta, body, None
    return None, text, "frontmatter is not closed by ---"


# --- writer ---------------------------------------------------------------------------------


@dataclass
class _Table:
    source: str
    table: str  # schema.table
    terms: list[str] = field(default_factory=list)
    #: column -> (type, description, notes)
    columns: dict[str, list[Any]] = field(default_factory=dict)
    path: str = ""


def _evidence_id(local: str) -> str:
    n = local.removeprefix("ev-")
    return f"e{n}" if n.isdigit() else slug(local)


def write(
    model: MergedOntology, out_dir: Path, *, revision: int, created_at: str
) -> dict[str, Any]:
    """Write ``<out_dir>/okf/``, validate it and return ``{files, validation}``; raises
    :class:`OkfError` (after writing ``validation.json``, which the export job copies to
    ``logs/`` because it removes the failed work folder) when the bundle is not
    conformant."""
    root = out_dir / OKF_DIR
    generated = {"by": GENERATOR, "at": created_at}
    aligned = model.aligned_terms()
    # judged same but not folded; matched by (documents source, name), not by label alone
    pending = {
        (e.get("source"), e.get("name")) for e in [*model.low_confidence, *model.dry_run_same]
    }

    # paths ------------------------------------------------------------------------------
    nodes: list[Any] = sorted(
        model.classes.values(), key=lambda c: (c.source != "structured", c.label, c.local)
    )
    nodes += sorted(model.individuals.values(), key=lambda i: (i.label, i.local))
    taken: set[str] = set()
    path_of: dict[str, str] = {}
    for node in nodes:
        path_of[node.local] = f"/concepts/{_unique(slug(node.label), taken)}.md"
    tables: dict[tuple[str, str], _Table] = {}
    for cls in model.classes.values():
        if cls.source != "structured":
            continue
        for table in cls.tables:
            t = tables.setdefault(
                (cls.structured_source, table), _Table(cls.structured_source, table)
            )
            t.terms.append(cls.local)
    for p in sorted(model.properties.values(), key=lambda p: p.local):
        if p.source not in ("structured", "semantic_fk"):
            continue
        table, _, column = p.source_column.rpartition(".")
        t = tables.setdefault((p.owner, table), _Table(p.owner, table))
        row = t.columns.setdefault(column, ["", "", []])
        if p.source == "structured":
            row[0], row[1] = p.datatype, p.comment
        else:
            row[2].append(
                f"refers to [{_escape(model.classes[p.range].label)}]({path_of[p.range]})"
            )
    taken = set()
    bare = {}
    for key in sorted(tables):
        name = key[1].rpartition(".")[2]
        bare.setdefault((key[0], name), []).append(key)
    for key in sorted(tables):
        name = key[1].rpartition(".")[2]
        stem = name if len(bare[(key[0], name)]) == 1 else key[1]
        tables[key].path = f"/tables/{_unique(slug(f'{key[0]}.{stem}'), taken)}.md"
    taken = set()
    doc_path: dict[str, str] = {}
    for d in sorted(model.documents.values(), key=lambda d: (d.path, d.local)):
        doc_path[d.local] = (
            f"/documents/{_unique(slug(PurePosixPath(d.path).name.replace('.', '-')), taken)}.md"
        )

    def link(local: str) -> str:
        label = (
            model.classes[local].label if local in model.classes else model.individuals[local].label
        )
        return f"[{_escape(label)}]({path_of[local]})"

    files: dict[str, str] = {}  # bundle path -> text

    # concepts ---------------------------------------------------------------------------
    outgoing: dict[str, list[str]] = {n.local: [] for n in nodes}
    for p in sorted(model.properties.values(), key=lambda p: (p.label, p.local)):
        if p.source == "semantic_fk" and p.domain in outgoing and p.range in path_of:
            column = p.source_column.rpartition(".")[2]
            outgoing[p.domain].append(f"refers to {link(p.range)} (column `{column}`)")
        elif p.source == "document" and p.subject_node in outgoing:
            target = p.value_concept or p.object_node
            if target not in path_of or target in (THING, LITERAL):
                continue
            words = p.predicate.replace("_", " ")
            note = "" if f" {p.predicate} " in f" {p.label} " else f" ({_escape(p.label)})"
            outgoing[p.subject_node].append(f"{words} {link(target)}{note}")
    for a in model.axioms:
        if a.subject not in outgoing or a.object not in path_of:
            continue
        if a.kind == "subclass_of":
            outgoing[a.subject].append(f"is a kind of {link(a.object)}")
        else:
            conf = f", confidence {a.confidence:.2f}" if a.confidence is not None else ""
            outgoing[a.subject].append(f"is related to {link(a.object)} ({a.source}{conf})")
    columns_of: dict[str, list[tuple[str, list[Any], _Table]]] = {}
    for t in tables.values():
        for term in t.terms:
            for col, row in sorted(t.columns.items()):
                columns_of.setdefault(term, []).append((col, row, t))
    concepts_of_doc: dict[str, list[str]] = {}

    for node in nodes:
        is_class = node.local in model.classes
        structured = is_class and node.source == "structured"
        kind = (node.kind or "term") if is_class else node.kind
        texts = [node.comment, *node.definitions] if is_class else [node.comment]
        texts = [t for t in dict.fromkeys(" ".join(str(t or "").split()) for t in texts) if t]
        sources = []
        evidence = [model.evidence[e] for e in node.derived_from if e in model.evidence]
        seen_ids: set[str] = set()
        for ev in evidence:
            doc = model.documents.get(ev.document)
            if doc is None or _evidence_id(ev.local) in seen_ids:
                continue
            seen_ids.add(_evidence_id(ev.local))
            concepts_of_doc.setdefault(ev.document, []).append(node.local)
            sources.append(
                {
                    "id": _evidence_id(ev.local),
                    "resource": document_resource(doc.path, doc.source),
                    "title": doc.title,
                }
            )
        tags = [f"origin:{model.origin(node.local, aligned)}", f"kind:{kind}"]
        for s in (getattr(node, "structured_source", ""), node.documents_source):
            if s:
                tags.append(f"source:{s}")
        meta: dict[str, Any] = {
            "type": CONCEPT_TYPE,
            "title": node.label,
            "description": _one_line(texts[0] if texts else f"{node.label} ({kind})"),
            "resource": f"{model.base}{node.local}",
            "tags": tags,
            "generated": dict(generated),
            "status": "draft"
            if not structured and (node.documents_source, node.label) in pending
            else "stable",
        }
        if sources:
            meta["sources"] = sources
        body = [f"# {_escape(node.label)}", ""]
        body += "\n\n".join(_escape(t) for t in texts).splitlines() or [
            f"{_escape(node.label)} ({kind})."
        ]
        if structured:
            body += ["", "# Schema", ""]
            backing = sorted(
                {t.path: t for t in (r[2] for r in columns_of.get(node.local, []))}.values(),
                key=lambda t: t.path,
            )
            backing = backing or [
                tables[(node.structured_source, t)]
                for t in node.tables
                if (node.structured_source, t) in tables
            ]
            if backing:
                body.append(
                    "Backed by "
                    + ", ".join(
                        f"[{_escape(t.source)}.{_escape(t.table)}]({t.path})" for t in backing
                    )
                    + "."
                )
                body.append("")
            body += _schema_table(columns_of.get(node.local, []))
        if outgoing[node.local]:
            body += ["", "# Relationships", ""] + [f"- {r}" for r in outgoing[node.local]]
        if node.alt_labels:
            body += ["", "# Synonyms", ""] + [f"- {_escape(s)}" for s in node.alt_labels]
        merges = [m for m in model.merges if m.term_local == node.local]
        if merges:
            body += ["", "# Alignment", ""]
            for m in merges:
                conf = f", confidence {m.confidence:.2f}" if m.confidence is not None else ""
                src = f" from {m.documents_source}" if m.documents_source else ""
                body.append(
                    f"- folded document concept {_escape(m.concept_name)} ({m.concept_kind}{src}{conf})"
                )
        if evidence:
            body += ["", "# Evidence", ""]
            notes = []
            done: set[str] = set()
            for ev in evidence:
                eid = _evidence_id(ev.local)
                doc = model.documents.get(ev.document)
                if doc is None or eid in done:
                    continue
                done.add(eid)
                body.append(f"- “{_escape(ev.quote)}”[^{eid}]")
                page = f", p. {ev.page}" if ev.page else ""
                notes.append(f"[^{eid}]: [{_escape(doc.title)}]({doc_path[doc.local]}){page}")
            body += [""] + notes
        files[path_of[node.local]] = frontmatter(meta) + "\n" + "\n".join(body) + "\n"

    # tables -----------------------------------------------------------------------------
    for t in sorted(tables.values(), key=lambda t: t.path):
        terms = [model.classes[x].label for x in t.terms]
        meta = {
            "type": "Table",
            "title": t.table,
            "description": _one_line(
                f"Table {t.table} of structured source {t.source}"
                + (f", represented by {', '.join(terms)}" if terms else "")
                + "."
            ),
            "resource": f"autoontology://{_iri_path(t.source)}/{_iri_path(t.table)}",
            "tags": ["origin:structured", "kind:table", f"source:{t.source}"],
            "generated": dict(generated),
            "status": "stable",
        }
        body = [f"# {_escape(t.table)}", "", "# Schema", ""]
        body += _schema_table([(c, row, t) for c, row in sorted(t.columns.items())])
        if t.terms:
            body += ["", "# Concepts", ""] + [f"- represented by {link(x)}" for x in t.terms]
        files[t.path] = frontmatter(meta) + "\n" + "\n".join(body) + "\n"

    # documents --------------------------------------------------------------------------
    for d in sorted(model.documents.values(), key=lambda d: doc_path[d.local]):
        concepts = sorted(set(concepts_of_doc.get(d.local, [])), key=lambda x: path_of[x])
        meta = {
            "type": "Document",
            "title": d.title or PurePosixPath(d.path).name,
            "description": _one_line(
                f"Source document {PurePosixPath(d.path).name} of {d.source}: "
                f"{len(concepts)} concept(s) extracted."
            ),
            "resource": document_resource(d.path, d.source),
            "tags": ["origin:document", "kind:document", f"source:{d.source}"],
            "generated": dict(generated),
            "status": "stable",
            "sha256": d.sha256,
        }
        body = [f"# {_escape(meta['title'])}", "", f"Path: `{d.path}`", ""]
        body += ["# Concepts", ""] + ([f"- {link(x)}" for x in concepts] or ["- (none)"])
        files[doc_path[d.local]] = frontmatter(meta) + "\n" + "\n".join(body) + "\n"

    # index and log ----------------------------------------------------------------------
    def describe(path: str) -> str:
        meta, _, _ = split_frontmatter(files[path])
        meta = meta or {}
        return f"* [{_escape(meta.get('title', path))}]({path}) - {_escape(meta.get('description', ''))}"

    index = [frontmatter({"okf_version": OKF_VERSION})]
    for heading, prefix in (
        ("Concepts", "/concepts/"),
        ("Tables", "/tables/"),
        ("Documents", "/documents/"),
    ):
        listed = sorted(p for p in files if p.startswith(prefix))
        if listed:
            index += ["", f"# {heading}", ""] + [describe(p) for p in listed]
    files["/index.md"] = "\n".join(index).replace("---\n\n\n", "---\n\n") + "\n"
    sources = ", ".join([*model.structured_sources, *model.documents_sources]) or "(none)"
    files["/log.md"] = (
        "# Update Log\n\n"
        f"## {created_at[:10]}\n\n"
        f"- revision r{revision:04d}: generated by autoontology {__version__} from sources "
        f"{sources}\n"
    )

    written: list[Path] = []
    for path, text in sorted(files.items()):
        target = root / path.lstrip("/")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding="utf-8")
        written.append(target)
    report = validate(root)
    (root / VALIDATION).write_text(
        json.dumps(report.to_dict(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )
    written.append(root / VALIDATION)
    if report.errors:
        shown = "; ".join(report.errors[:10])
        raise OkfError(f"OKF validation failed ({len(report.errors)} error(s)): {shown}")
    return {"files": written, "validation": report.to_dict()}


def _schema_table(rows: list[tuple[str, list[Any], Any]]) -> list[str]:
    if not rows:
        return ["(no columns)"]
    out = ["| Column | Type | Description |", "|---|---|---|"]
    for col, (dtype, desc, notes), _ in rows:
        text = "; ".join([_escape(desc)] * bool(desc) + notes)
        out.append(f"| `{col.replace('|', '')}` | {_escape(dtype) or '-'} | {text} |")
    return out


# --- validation -----------------------------------------------------------------------------


@dataclass
class Report:
    files: int = 0
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.errors

    def to_dict(self) -> dict[str, Any]:
        return {
            "okf_version": OKF_VERSION,
            "ok": self.ok,
            "files": self.files,
            "errors": self.errors,
            "warnings": self.warnings,
        }


def validate(bundle: Path) -> Report:
    """OKF v0.2 conformance (§11) of the bundle at *bundle*: every non-reserved ``.md``
    has a YAML frontmatter mapping with a non-empty string ``type``; ``index.md`` has no
    frontmatter except ``okf_version`` at the bundle root; ``log.md`` has none and dates
    its ``##`` headings ``YYYY-MM-DD``; a reserved file used as a concept is an error.
    Broken links and footnotes without a ``sources`` entry are warnings (§6.1: consumers
    tolerate them)."""
    bundle = bundle.resolve()
    report = Report()
    for path in sorted(bundle.rglob("*.md")):
        rel = path.relative_to(bundle).as_posix()
        report.files += 1
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            report.errors.append(f"{rel}: not UTF-8")
            continue
        meta, body, error = split_frontmatter(text)
        if path.name in RESERVED:
            if error:
                report.errors.append(f"{rel}: {error}")
            elif meta is not None:
                if "type" in meta:
                    report.errors.append(f"{rel}: reserved file name used for a concept")
                elif path.name == "log.md" or rel != "index.md":
                    report.errors.append(f"{rel}: {path.name} takes no frontmatter here")
                elif set(meta) - {"okf_version"}:
                    extra = ", ".join(sorted(map(str, set(meta) - {"okf_version"})))
                    report.errors.append(
                        f"{rel}: index.md frontmatter allows only okf_version ({extra})"
                    )
                elif not isinstance(meta.get("okf_version"), str):
                    report.errors.append(f'{rel}: okf_version must be a string such as "0.2"')
            if path.name == "log.md":
                dates = []
                for line in body.splitlines():
                    if line.startswith("## "):
                        heading = line[3:].strip()
                        if not _DATE.fullmatch(heading):
                            report.errors.append(
                                f"{rel}: log heading {heading!r} is not YYYY-MM-DD"
                            )
                        else:
                            dates.append(heading)
                if dates != sorted(dates, reverse=True):
                    report.warnings.append(f"{rel}: entries are not newest first")
        else:
            if error:
                report.errors.append(f"{rel}: {error}")
                continue
            if meta is None:
                report.errors.append(f"{rel}: no frontmatter")
                continue
            kind = meta.get("type")
            if not isinstance(kind, str) or not kind.strip():
                report.errors.append(f"{rel}: frontmatter has no non-empty type")
            ids = {
                str(s.get("id"))
                for s in meta.get("sources") or []
                if isinstance(s, dict) and s.get("id") is not None
            }
            for ref in sorted(set(_FOOTNOTE_REF.findall(body))):
                if ref not in ids:
                    report.warnings.append(f"{rel}: footnote [^{ref}] has no sources entry")
        for target in _LINK.findall(body):
            if _SCHEME.match(target) or target.startswith("#"):
                continue
            clean = unquote(target.split("#", 1)[0])
            if not clean:
                continue
            dest = (bundle / clean.lstrip("/")) if clean.startswith("/") else (path.parent / clean)
            dest = Path(unicodedata.normalize("NFC", str(dest)))
            try:
                inside = dest.resolve().is_relative_to(bundle)
            except OSError:
                inside = False
            if not inside or not dest.exists():
                report.warnings.append(f"{rel}: broken link {target}")
    return report
